+var SILENT_UPDATE_MAX_FAILURES = 3;
+var SILENT_UPDATE_DEGRADED_LABEL = 'silent-update-degraded';
+var SILENT_UPDATE_MARKER_RE = /⚠️ silent-update failure — attempt (\d+) at (\S+)/g;
