            if (opts.onAddLabel) opts.onAddLabel(labelOpts);
        },
        jira_remove_label: function() {},
        jira_move_to_status: function(moveOpts) {
            capturedStatusMoves.push(moveOpts);
            if (opts.onMoveStatus) opts.onMoveStatus(moveOpts);
        },

