    });
    return out;
}

function setOf(list) {
    var s = {};
    list.forEach(function (n) { s[n] = true; });
    return s;
}

function armedExtrasOf(labelHolders, candSet) {
    var out = [];
    labelHolders.forEach(function (n) {
        if (!candSet[n]) out.push(n);
